// OCR.space returns ParsedResults[0].ParsedText; normalize to .text
const r = $input.first().json;
const text = (r.ParsedResults && r.ParsedResults[0] && r.ParsedResults[0].ParsedText) || r.text || '';
return [{ json: { text }, binary: $input.first().binary }];

// Build the routing menu for the LLM: resume excerpt + numbered list of openings.
// Also compute a cheap keyword-overlap fallback pick used only if the LLM call fails.
const resumeText = String($input.first().json.text || '').replace(/\s+/g, ' ').trim();
let reqs = [];
try { reqs = JSON.parse($('Webhook').first().json.body.requirements || '[]'); } catch (e) {}
if (!Array.isArray(reqs)) reqs = [];

const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const cut = (s, n) => clean(s).slice(0, n);

const menu = reqs.map((r, i) =>
  `[${i + 1}] ${cut(r.job_title, 120)}\n    Description: ${cut(r.description, 600)}\n    Qualifications: ${cut(r.qualifications, 600)}`
).join('\n\n');

const reqIds = reqs.map((r) => r.requirement_id);

// Cheap keyword-overlap fallback (no external call).
const stop = new Set(('a an and or the to of in for with on at by from as is are be we you your our their they will who this that role job work works working experience years ability strong good skills knowledge team teams including etc').split(' '));
const toks = (s) => String(s || '').toLowerCase().match(/[a-z][a-z+#.]{1,}/g) || [];
const resumeSet = new Set(toks(resumeText).filter((w) => !stop.has(w)));
let fbIdx = 0, fbBest = -1;
reqs.forEach((r, i) => {
  const rt = toks(`${r.job_title} ${r.qualifications} ${r.description}`).filter((w) => !stop.has(w));
  const seen = new Set();
  let hit = 0;
  rt.forEach((w) => { if (!seen.has(w)) { seen.add(w); if (resumeSet.has(w)) hit++; } });
  const score = seen.size ? hit / Math.sqrt(seen.size) : 0;
  if (score > fbBest) { fbBest = score; fbIdx = i; }
});

return [{ json: {
  resume_excerpt: resumeText.slice(0, 6000),
  req_menu: menu,
  req_count: reqs.length,
  req_ids: JSON.stringify(reqIds),
  fallback_id: reqIds[fbIdx] || (reqIds[0] || null),
} }];

// Map the LLM's chosen index back to a requirement_id, with validation + fallback.
const rawOut = $input.first().json.output || $input.first().json.content || $input.first().json.text || '';
const ctx = $('Build Prompt Context').first().json;
let reqIds = [];
try { reqIds = JSON.parse(ctx.req_ids || '[]'); } catch (e) {}
const fallbackId = ctx.fallback_id || (reqIds[0] || null);

let parsed = null;
try {
  const m = String(rawOut).replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : rawOut);
} catch (e) { parsed = null; }

const idx = parsed ? Number(parsed.best_index) : NaN;
let bestId, reason;
if (Number.isInteger(idx) && idx >= 1 && idx <= reqIds.length) {
  bestId = reqIds[idx - 1];
  reason = (parsed && parsed.reason) ? String(parsed.reason).slice(0, 200) : 'LLM match';
} else {
  bestId = fallbackId;
  reason = 'fallback (keyword overlap)';
}

return [{ json: { best_requirement_id: bestId, best_score: null, best_reason: reason } }];
